package org.synapseworks.pageharbor.validation
import android.app.*
import android.os.*
import android.net.Uri
import java.io.File
import java.util.UUID
import org.json.*
import com.tom_roush.pdfbox.android.PDFBoxResourceLoader
import org.synapseworks.pageharbor.integrity.*
import org.synapseworks.pageharbor.workflow.*

/** Independent public frozen PDFs; provider injection supplements genuine picker qualification. */
class IntegrityChecks:Instrumentation(){
 override fun onCreate(args:Bundle?){super.onCreate(args);start()}
 override fun onStart(){val result=Bundle();val root=File(targetContext.cacheDir,"m40-check-"+UUID.randomUUID());var vm:IntegrityViewModel?=null
 try{check(targetContext.packageName.endsWith(".m36packsmoke")||targetContext.packageName.endsWith(".m36packr8"));check(root.mkdir());PDFBoxResourceLoader.init(targetContext);val crypto=org.bouncycastle.jce.provider.BouncyCastleProvider();for((kind,algorithm)in listOf("MessageDigest" to "SHA-256","Signature" to "SHA256WITHRSA","CertificateFactory" to "X.509")){check(crypto.getService(kind,algorithm)?.newInstance(null)!=null)};result.putBoolean("privateCryptoServices",true);val evidence=File(targetContext.cacheDir,"m40-evidence").apply{mkdirs()};val corpus=JSONObject(targetContext.assets.open("m40-corpus.json").bufferedReader().use{it.readText()});val manifest=corpus.getJSONArray("fixtures");val inputs=mutableMapOf<String,File>();val documents=mutableMapOf<String,IntegrityDocument>();val signatures=JSONArray();val started=SystemClock.elapsedRealtime()
  for(i in 0 until manifest.length()){val row=manifest.getJSONObject(i);val name=row.getString("name");val file=File(root,name).apply{targetContext.assets.open("m40/$name").use{source->outputStream().use{source.copyTo(it)}}};check(java.security.MessageDigest.getInstance("SHA-256").digest(file.readBytes()).joinToString(""){"%02x".format(it)}==row.getString("sha256"));inputs[name]=file;result.putString("stage",name);val doc=IntegrityEngine.inspect(file,root,"fixture-$i"){};documents[name]=doc;doc.signatures.forEach{signatures.put(JSONObject().put("file",name).put("format",it.format).put("binding",it.binding).put("coverage",it.coverage).put("certificateTime",it.certificateTime));File(evidence,"signatures.json").writeText(signatures.toString(2));check(it.report().contains("Trust: NOT_ASSESSED")&&it.report().contains("Revocation/freshness/AIA/OCSP/CRL: NOT_CHECKED"))}}
  File(evidence,"signatures.json").writeText(signatures.toString(2));check(documents["valid-signed.pdf"]!!.signatures.single().binding=="VALID");check(documents["tampered.pdf"]!!.signatures.single().binding=="INVALID");check(documents["appended.pdf"]!!.signatures.single().binding=="VALID"&&documents["appended.pdf"]!!.signatures.single().coverage.startsWith("EARLIER_BYTES_ONLY"));check(documents["malformed-range.pdf"]!!.signatures.single().binding=="NOT_CHECKED");check(documents["unsupported.pdf"]!!.signatures.single().binding=="UNSUPPORTED");check(documents["baseline.pdf"]!!.signatures.isEmpty());File(evidence,"signatures.json").writeText(signatures.toString(2));result.putInt("signatureCases",6)
  val omitted=File(root,"omitted.pdf").apply{targetContext.assets.open("m40-type-omitted-control.pdf").use{input->outputStream().use{input.copyTo(it)}}};val omittedResult=IntegrityEngine.inspect(omitted,root,"omitted"){};check(omittedResult.signatures.size==1&&omittedResult.signatures.single().binding=="INVALID");result.putBoolean("optionalTypePresenceAndTamperControl",true)
  val compares=corpus.getJSONArray("comparisons");val comparisons=JSONArray()
  for(i in 0 until compares.length()){val c=compares.getJSONObject(i);val a=documents[c.getString("a")]!!;val b=documents[c.getString("b")]!!;val differences=IntegrityRules.compare(a,b);val exact=IntegrityRules.bytesEqual(inputs[c.getString("a")]!!,inputs[c.getString("b")]!!);if(c.has("bytes"))check(exact==(c.getString("bytes")=="EQUAL"));if(c.has("text"))check(differences.first().text.startsWith(if(c.getString("text")=="NO_NATIVE_TEXT")"NO_NATIVE_TEXT"else"EXTRACTED_TEXT_"+c.getString("text")));if(c.has("pixels"))check(differences.first().visual=="RENDERED_PIXELS_"+c.getString("pixels"));if(c.has("addedPages"))check(differences.count{it.visual=="ADDED_PAGE"}==1);if(c.has("missingPages"))check(differences.count{it.visual=="MISSING_PAGE"}==1);comparisons.put(JSONObject().put("a",c.getString("a")).put("b",c.getString("b")).put("byteEqual",exact).put("pages",JSONArray(differences.map{JSONObject().put("page",it.page).put("text",it.text).put("visual",it.visual).put("changedPixels",it.changed)})))}
  File(evidence,"comparisons.json").writeText(comparisons.toString(2));result.putInt("comparisonCases",compares.length());result.putLong("allFixtureInspectionMs",SystemClock.elapsedRealtime()-started)
  fun idle(){repeat(1000){if(vm!!.busy)Thread.sleep(20)};check(!vm!!.busy)}
  var current=true;runOnMainSync{vm=IntegrityViewModel(targetContext.applicationContext as Application);vm!!.open{current}};idle()
  fun select(name:String,baseline:Boolean){runOnMainSync{val ticket=vm!!.beginPick(baseline);check(ticket!=null);vm!!.selected(ticket,Uri.fromFile(inputs[name]!!))};idle();check(if(baseline)vm!!.baseline!=null else vm!!.comparison!=null)}
  select("valid-signed.pdf",true);select("appended.pdf",false);runOnMainSync{vm!!.inspect()};idle();check(vm!!.left?.signatures?.single()?.binding=="VALID"&&vm!!.right?.signatures?.single()?.coverage?.startsWith("EARLIER_BYTES_ONLY")==true);val report=vm!!.report;check(report.contains("Trust: NOT_ASSESSED")&&!report.contains("file://")&&!report.contains("content://"));File(evidence,"expected-report.txt").writeText(report)
  val target=File(root,"Integrity-report.txt").apply{createNewFile()};IntegrityControlProvider.file=target;val uri=Uri.parse("content://"+targetContext.packageName+".m40-control/owned-control")
  runOnMainSync{vm!!.reviewed=true;check(vm!!.beginSave()!=null);val old=vm!!.saveTicket;vm!!.destination(old,null);check(vm!!.beginSave()!=null);vm!!.destination(old,uri);check(vm!!.picker&&target.length()==0L);check(vm!!.beginPick(true)==null);vm!!.destination(vm!!.saveTicket,uri)};idle();check(vm!!.message.startsWith("Separate reviewed report saved")&&target.readText()==report);target.copyTo(File(evidence,"saved-report.txt"),true)
  val original=inputs["valid-signed.pdf"]!!.readBytes();IntegrityControlProvider.file=inputs["valid-signed.pdf"];runOnMainSync{check(vm!!.beginSave()!=null);vm!!.destination(vm!!.saveTicket,uri)};idle();check(vm!!.message.startsWith("Save refused")&&inputs["valid-signed.pdf"]!!.readBytes().contentEquals(original))
  val guard=workflowSourceGuard(targetContext,Uri.fromFile(inputs["valid-signed.pdf"]!!));android.os.ParcelFileDescriptor.open(inputs["valid-signed.pdf"],android.os.ParcelFileDescriptor.MODE_READ_ONLY).use{check(!workflowDifferentSources(targetContext,it,uri,listOf(guard)))}
  target.writeBytes(byteArrayOf());IntegrityControlProvider.file=target;IntegrityControlProvider.entered=java.util.concurrent.CountDownLatch(1);IntegrityControlProvider.release=java.util.concurrent.CountDownLatch(1);runOnMainSync{check(vm!!.beginSave()!=null);vm!!.destination(vm!!.saveTicket,uri)};check(IntegrityControlProvider.entered!!.await(2,java.util.concurrent.TimeUnit.SECONDS));runOnMainSync{vm!!.close()};check(target.length()==0L);IntegrityControlProvider.release!!.countDown();Thread.sleep(100);check(target.length()==0L);IntegrityControlProvider.release=null;IntegrityControlProvider.entered=null
  runOnMainSync{vm!!.open{current}};idle();select("baseline.pdf",true);select("equivalent.pdf",false);val oldToken=vm!!.interactionToken;runOnMainSync{vm!!.inspect();vm!!.close();vm!!.interact(oldToken){vm!!.inspect()}};Thread.sleep(100);check(!vm!!.visible&&vm!!.report.isEmpty())
  runOnMainSync{vm!!.open{current}};idle();select("baseline.pdf",true);runOnMainSync{current=false;vm!!.changed()};check(!vm!!.visible&&vm!!.baseline==null)
  check(inputs["valid-signed.pdf"]!!.readBytes().contentEquals(original));result.putString("stage","complete");result.putString("status","PASS");result.putString("scope","Frozen6 comparisons/6 signature decisions; reviewed exact report, source integrity, stale tickets/input, direct/provider aliases, blocked-write Close, cancellation and source invalidation")
 }catch(t:Throwable){result.putString("status","FAIL");result.putString("failureClass",t.javaClass.simpleName);result.putString("sanitizedFrames",t.stackTrace.take(8).joinToString(";"){it.className+"."+it.methodName+":"+it.lineNumber});result.putString("causeClasses",generateSequence(t){it.cause}.take(4).joinToString("->"){it.javaClass.name});result.putInt("failureLine",t.stackTrace.firstOrNull{it.className.endsWith("IntegrityChecks")}?.lineNumber?:-1)}finally{IntegrityControlProvider.release?.countDown();IntegrityControlProvider.file=null;runOnMainSync{vm?.close()};root.deleteRecursively()};finish(Activity.RESULT_OK,result)}
}
